                            .iter_mut()
                            .rev()
310→                            .find(|e| e.state == WorkingState::TurnCompleted)
                    {
                        ev.token_usage = Some(usage.clone());
                    }
                    self.token_usage = Some(usage);
                }
                if let Some(c) = json.get("total_cost_usd").and_then(Value::as_f64) {
                    self.total_cost_usd = Some(c);
                }
